-- =============================================================================
-- Jean-Michel — SQLite schema (v2 consolidated)
-- =============================================================================
-- This file represents the canonical v2 state of the database, equivalent to :
--   schema.sql (v1 baseline) + migrate_100_paradigm_realignment.sql
--   + migrate_101_user_memory.sql + migrate_102_drop_runtime_tables.sql
--   + migrate_103_search_quality.sql + migrate_104_drop_conv_read_file.sql
--   + migrate_105_strategist_agent.sql + migrate_106_news_specialist.sql
--   + migrate_107_news_routing_and_web_fetch.sql + migrate_108_code_fetcher_agent.sql
--   + migrate_109_code_runner_routing_and_sandbox.sql
--   + migrate_110_syntax_check_before_run.sql
--   + migrate_111_code_runner_to_reasoner.sql
--   + migrate_112_web_users.sql + migrate_113_user_memory_isolation.sql
--   + migrate_114_conversation_cascade.sql
--
-- It is regenerated by `sqlite3 .dump` after applying the v2 migrations to a
-- fresh v1 database. Fresh installs load this file directly via
-- `./jm.sh --install` ; existing v1 instances should apply the individual
-- migrations under db/migrations/ instead.
--
-- v2 architecture reference : DevNotes/REVOLUCION/06_proposition_v2.md
-- =============================================================================
CREATE TABLE sections (
  id             INTEGER PRIMARY KEY,
  code           TEXT UNIQUE NOT NULL,
  title          TEXT NOT NULL,
  order_priority INTEGER NOT NULL DEFAULT 100,   -- 0 = top
  active         INTEGER NOT NULL DEFAULT 1,
  created_at     TEXT NOT NULL,
  modified_at    TEXT NOT NULL
);
CREATE TABLE categories (
  id             INTEGER PRIMARY KEY,
  section_id     INTEGER NOT NULL REFERENCES sections(id),
  code           TEXT NOT NULL,
  title          TEXT NOT NULL,
  order_priority INTEGER NOT NULL DEFAULT 100,
  active         INTEGER NOT NULL DEFAULT 1,
  created_at     TEXT NOT NULL,
  modified_at    TEXT NOT NULL,
  UNIQUE (section_id, code)
);
CREATE TABLE paradigms (
  id             INTEGER PRIMARY KEY,
  category_id    INTEGER NOT NULL REFERENCES categories(id),
  code           TEXT UNIQUE NOT NULL,
  title          TEXT NOT NULL,
  content        TEXT NOT NULL,         -- markdown bullets, injected verbatim
  rationale      TEXT,                  -- internal note, never injected
  is_global      INTEGER NOT NULL DEFAULT 0,
  order_priority INTEGER NOT NULL DEFAULT 100,
  active         INTEGER NOT NULL DEFAULT 1,
  created_at     TEXT NOT NULL,
  modified_at    TEXT NOT NULL
);
CREATE TABLE paradigm_modes (
  paradigm_id INTEGER NOT NULL REFERENCES paradigms(id) ON DELETE CASCADE,
  mode        TEXT    NOT NULL CHECK (mode IN ('analyse','chat','vocal')),
  PRIMARY KEY (paradigm_id, mode)
);
CREATE TABLE agents (
  id             INTEGER PRIMARY KEY,
  code           TEXT UNIQUE NOT NULL,
  name           TEXT NOT NULL,
  role           TEXT NOT NULL CHECK (role IN ('router','specialist','finalizer')),
  -- NOTE: 'planner' role deprecated and removed by migration 044.
  mission        TEXT NOT NULL,
  thinking_mode  INTEGER NOT NULL DEFAULT 1,
  temperature    REAL NOT NULL DEFAULT 0.2,
  active         INTEGER NOT NULL DEFAULT 1,
  sandbox_image  TEXT,                        -- Docker image override for bash_sandbox (NULL = system default)
  created_at     TEXT NOT NULL,
  modified_at    TEXT NOT NULL
, model_override TEXT NULL);
CREATE TABLE agent_paradigms (
  agent_id       INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  paradigm_id    INTEGER NOT NULL REFERENCES paradigms(id) ON DELETE CASCADE,
  PRIMARY KEY (agent_id, paradigm_id)
);
CREATE TABLE agent_tools (
  agent_id       INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  tool_code      TEXT NOT NULL,
  PRIMARY KEY (agent_id, tool_code)
);
CREATE TABLE agent_workspace_grants (
  agent_id       INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  PRIMARY KEY (agent_id)
);
CREATE TABLE agent_sandbox_grants (
  agent_id       INTEGER NOT NULL REFERENCES agents(id) ON DELETE CASCADE,
  command        TEXT NOT NULL,
  PRIMARY KEY (agent_id, command)
);
CREATE TABLE conversations (
  id             TEXT PRIMARY KEY,            -- UUID
  title          TEXT,
  folder_path    TEXT NOT NULL,
  user_language  TEXT,                        -- detected via langdetect
  status         TEXT NOT NULL DEFAULT 'active',
  mode           TEXT NOT NULL DEFAULT 'analyse'
                 CHECK (mode IN ('analyse','chat','vocal')),
  task_class     TEXT,                        -- 'single_fact' | 'medium_task' | 'deep_research'
  current_phase  TEXT,                        -- NULL | 'planner_done' | 'gather_done' | 'critic_done' | 'build_done'
  created_at     TEXT NOT NULL,
  modified_at    TEXT NOT NULL
);
CREATE TABLE agent_delegation_targets (
  agent_id    INTEGER NOT NULL REFERENCES agents(id),
  target_code TEXT NOT NULL,
  created_at  TEXT NOT NULL DEFAULT (datetime('now')),
  PRIMARY KEY (agent_id, target_code)
);
CREATE TABLE user_memory (
    id           INTEGER PRIMARY KEY,
    user_id      INTEGER NOT NULL REFERENCES web_users(id),
    type         TEXT NOT NULL CHECK (type IN ('user', 'feedback', 'project', 'reference')),
    code         TEXT NOT NULL,
    title        TEXT NOT NULL,
    description  TEXT NOT NULL,  -- one-line hook, injected into the prompt index
    content      TEXT NOT NULL,  -- full markdown body, loaded on demand via recall
    created_at   TEXT NOT NULL,
    modified_at  TEXT NOT NULL,
    UNIQUE (user_id, type, code)
);
CREATE INDEX idx_agent_tools_agent ON agent_tools(agent_id);
CREATE INDEX idx_user_memory_user ON user_memory(user_id);
CREATE INDEX idx_user_memory_type ON user_memory(type);
CREATE INDEX idx_user_memory_modified ON user_memory(modified_at DESC);
CREATE TABLE web_users (
  id            INTEGER PRIMARY KEY,
  username      TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  created_at    TEXT NOT NULL,
  name          TEXT NOT NULL DEFAULT '',
  birthdate     TEXT NOT NULL DEFAULT '',
  city          TEXT NOT NULL DEFAULT '',
  country       TEXT NOT NULL DEFAULT '',
  language      TEXT NOT NULL DEFAULT '',
  interests     TEXT NOT NULL DEFAULT '',
  notes         TEXT NOT NULL DEFAULT ''
);
CREATE TABLE conversation_users (
  user_id         INTEGER NOT NULL REFERENCES web_users(id)     ON DELETE CASCADE,
  conversation_id TEXT    NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,
  created_at      TEXT    NOT NULL,
  PRIMARY KEY (user_id, conversation_id)
);
CREATE INDEX idx_conv_users_user ON conversation_users(user_id);
